targets.expr:
avg((time() - max by (cluster, hosted_cluster_namespace) (
  label_replace(
    max without (prometheus_replica) (
      velero_backup_last_successful_timestamp{cluster="$cluster", schedule=~"${hcp_namespace:regex}-6-hourly"}
    ),
    "hosted_cluster_namespace", "$1", "schedule", "(.+)-6-hourly"
  )
)) <= bool 12 * 3600) * 100

max((time() - max by (cluster, hosted_cluster_namespace) (
  label_replace(
    max without (prometheus_replica) (
      velero_backup_last_successful_timestamp{cluster="$cluster", schedule=~"${hcp_namespace:regex}-6-hourly"}
    ),
    "hosted_cluster_namespace", "$1", "schedule", "(.+)-6-hourly"
  )
)) / 3600)

(time() - max by (cluster, hosted_cluster_namespace) (
  label_replace(
    max without (prometheus_replica) (
      velero_backup_last_successful_timestamp{cluster="$cluster", schedule=~"${hcp_namespace:regex}-6-hourly"}
    ),
    "hosted_cluster_namespace", "$1", "schedule", "(.+)-6-hourly"
  )
))/3600

(count by (cluster) (
  max without (prometheus_replica) (
    velerobackup_phase{cluster="$cluster", phase=~"New|Queued|ReadyToStart|InProgress|WaitingForPluginOperations|WaitingForPluginOperationsPartiallyFailed|Finalizing|FinalizingPartiallyFailed"}
  ) == 1
) or on() vector(0))

